        "Pourquoi utiliser un générateur plutôt que rédiger l’expression à la main ? Parce que cron va à l’encontre de l’intuition : le jour de la semaine vaut-il 0 ou 7 ? Une étoile dans le champ jour du mois combinée au jour de la semaine signifie-t-elle OU plutôt que ET ? Même les professionnels se font piéger, et le générateur configure les champs avec précision.",
