        "हाथ से लिखने के बजाय जनरेटर क्यों? क्योंकि cron को सहज रूप से समझना कठिन है: सप्ताह का दिन 0 है या 7? क्या महीने के दिन और सप्ताह के दिन में स्टार का साथ होना AND नहीं, बल्कि OR दर्शाता है? पेशेवर भी इन उलझनों में फँस जाते हैं; जनरेटर इन्हें सटीक रूप से सेट करता है।",
