        "तैयार और लोकप्रिय उदाहरण: 0 3 * * * (सुबह 3 बजे बैकअप), */15 * * * * (हर 15 मिनट में हेल्थ चेक), 0 0 1 * * (हर महीने की 1 तारीख़ को रिपोर्ट)।"
