        "L’algorithme de comparaison (LCS, plus longue sous-séquence commune) distingue assez bien les véritables ajouts et suppressions des simples déplacements de lignes — la différence entre un rapport lisible et du bruit incompréhensible.",
        "Le mode caractère est précieux pour les comparaisons précises : un simple espace dans un mot de passe ou une virgule dans du JSON — des détails minuscules qui peuvent casser des systèmes et passer inaperçus lors d’une comparaison ligne par ligne.",
